with lines as (select id, plan, currency, explode_outer(tier_limits) as val from price_tiers) select case when val >= 88 then 'PREMIUM' else 'STANDARD' end as val_tier, round(sum(val) / nullif(count(case when plan = 'starter' then 1 end), 0), 2) as val_per_starter, round(avg(val), 2) as avg_val, count_if(currency = 'THB') as thb_events, sum(val) as total_val, round(sum(val) / nullif(count(case when currency = 'EUR' then 1 end), 0), 2) as val_per_eur, round(avg(val), 2) as avg_val_2 from lines group by val_tier having sum(val) < 0 order by avg_val desc;
